script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('threat.framework', 'MITRE ATT&CK');
        v.get('_source').put('threat.technique.id', 'T1595, T1590, T1046');
        v.get('_source').put('threat.technique.name', 'Active Scanning, Gather Victim Network Information, Network Service Scanning');
        v.get('_source').put('threat.technique.reference', 'https://attack.mitre.org/techniques/T1595, https://attack.mitre.org/techniques/T1590, https://attack.mitre.org/techniques/T1046');
        v.get('_source').put('threat.tactic.id', 'TA0043, TA0007');
        v.get('_source').put('threat.tactic.name', 'Reconnaissance, Discovery');
        v.get('_source').put('threat.tactic.reference', 'https://attack.mitre.org/tactics/TA0043, https://attack.mitre.org/tactics/TA0007');
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'Detection of Reconnaissance Attack');
        v.get('_source').put('threat.detection_description', 'AWS Guardduty detects any reconnaissance related attacks.');
        v.get('_source').put('threat.severity', 'medium');
        v.get('_source').put('threat.triage_score', 40);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
